import re

def is_valid_time(time_str):
    match = re.match(r'^\d{1,2}:\d{2}(:\d{2})?$', time_str)
    if match:
        hour, minute, second = match.groups(1)
        if (0 <= int(hour) <= 23) and (0 <= int(minute) <= 59):
            return True
    return False

