def find_move(board, player):
  moves = board.list_moves(player)
  for move in moves:
    board.make_move(player, move)
    if board.has_won(player):
      return move
    board.unmake_move(player, move)

  # Check for Forks
  for move in moves:
    board.make_move(player, move)
    wins = 0
    for opponent_move in board.list_moves(board.next_player(player)):
      board.make_move(board.next_player(player), opponent_move)
      if board.has_won(board.next_player(player)):
        wins += 1
      board.unmake_move(board.next_player(player), opponent_move)
    if wins > 1:
      return move
    board.unmake_move(player, move)

  # Check for Center
  if board.center_empty():
    return 4

  # Check for Opposite Corner
  if board.corner_filled_by(board.next_player(player)):
    opposite = {
      0: 8,
      2: 6,
      6: 2,
      8: 0
    }
    for corner, opp in opposite.items():
      if board.is_marked(corner):
        if board.is_empty(opp):
          return opp

  # Check for Empty Corner
  for corner in (0, 2, 6, 8):
    if board.is_empty(corner):
      return corner

  # Check for Empty Side
  for side in (1, 3, 5, 7):
    if board.is_empty(side):
      return side

  return None

