import os

def photo_details(request, photo_id):
    try:
        photo = Photo.objects.get(pk=photo_id)
    except Photo.DoesNotExist:
        return HttpResponseNotFound("Photo not found.")

    try:
        fs = FileSystemStorage()
        image_url = os.path.join('media', photo.image.url)
        image = Image.open(fs.path(image_url))

        details = {'exif': list(image.getexif().items())}
        return render(request, 'photo_detail.html', {'photo': photo, 'details': details})

    except Exception as e:
        return HttpResponseServerError("Error processing photo: " + str(e))

