NEPOTISM_SUSPECTS = [
    r'^john\.doe@domain\.com$',
    r'^jane\.doe@domain\.com$',
    r'^jim\.smith@domain\.com$'
]

def clean_email(email):
    return re.sub(r'[^a-zA-Z0-9._%@]', '', email)

def clean_invites(filename):
    with open(filename) as f:
        cleaned = []
        for line in f:
            cleaned.append(clean_email(line))
    return cleaned

def send_invites(invites):
    for email in invites:
        if any(re.match(suspect, email) for suspect in NEPOTISM_SUSPECTS):
            print(f'Skipping invite to suspicious email address: {email}')
        else:
            print(f'Sending invite to {email}')


